INSERT INTO education_modules (title, category, content_type, summary, order_index, body, quiz) VALUES
(
	'Apa Itu Bullying?',
	'Dasar',
	'article',
	'Kenali definisi bullying dan bedanya dengan konflik biasa.',
	1,
	E'Bullying atau perundungan adalah perilaku agresif yang dilakukan berulang kali oleh seseorang atau sekelompok orang yang memiliki kekuatan lebih besar terhadap orang lain yang lebih lemah.\n\nAda tiga ciri utama bullying:\n\n1. **Disengaja** — pelaku sadar bahwa perbuatannya menyakiti.\n2. **Berulang** — terjadi berkali-kali, bukan sekali lalu selesai.\n3. **Ada ketimpangan kekuatan** — pelaku merasa lebih kuat, lebih populer, atau lebih berkuasa.\n\nBullying berbeda dengan pertengkaran biasa. Dalam pertengkaran, kedua pihak punya kekuatan yang seimbang dan biasanya bisa berbaikan. Dalam bullying, korban merasa tidak berdaya untuk melawan.\n\nIngat: kalau kamu mengalami ini, itu bukan salahmu. Tidak ada orang yang pantas dirundung.',
	'[{"question":"Manakah yang BUKAN ciri utama bullying?","options":["Dilakukan dengan sengaja","Terjadi berulang kali","Kedua pihak sama-sama kuat","Ada ketimpangan kekuatan"],"correct_index":2},{"question":"Jika kamu menjadi korban bullying, itu adalah...","options":["Salahmu sendiri","Bukan salahmu","Hal yang wajar","Tanda kamu lemah"],"correct_index":1}]'
),
(
	'Jenis-Jenis Bullying',
	'Dasar',
	'article',
	'Bullying tidak selalu berupa kekerasan fisik.',
	2,
	E'Bullying punya banyak bentuk, dan tidak semuanya meninggalkan luka yang terlihat.\n\n**1. Fisik**\nMemukul, menendang, mendorong, merusak atau mengambil barang milik orang lain.\n\n**2. Verbal**\nMengejek, memberi julukan yang menyakitkan, menghina, mengancam.\n\n**3. Sosial (relasional)**\nSengaja mengucilkan seseorang, menyebarkan gosip, mengajak orang lain untuk menjauhi korban.\n\n**4. Cyberbullying**\nMerundung lewat media digital: menyebar foto tanpa izin, mengirim pesan kasar, membuat akun palsu untuk mempermalukan.\n\nBullying verbal dan sosial sering dianggap "cuma bercanda", padahal dampaknya bisa sama beratnya dengan kekerasan fisik.',
	'[{"question":"Sengaja mengucilkan teman dari kelompok termasuk bullying jenis...","options":["Fisik","Verbal","Sosial","Bukan bullying"],"correct_index":2},{"question":"Menyebarkan foto memalukan teman di grup chat termasuk...","options":["Cyberbullying","Bercanda biasa","Bullying fisik","Bukan masalah"],"correct_index":0}]'
),
(
	'Dampak Bullying',
	'Dampak',
	'article',
	'Memahami efek bullying bagi korban, pelaku, dan saksi.',
	3,
	E'Bullying meninggalkan bekas yang tidak selalu terlihat dari luar.\n\n**Bagi korban**\nSulit tidur, cemas saat berangkat sekolah, nilai menurun, kehilangan kepercayaan diri, menarik diri dari teman. Dalam kasus berat bisa berlanjut menjadi depresi.\n\n**Bagi pelaku**\nTerbiasa menyelesaikan masalah dengan kekerasan, sulit membangun hubungan sehat, berisiko terlibat masalah yang lebih besar di kemudian hari.\n\n**Bagi saksi**\nMerasa takut dan bersalah karena tidak menolong, atau lama-lama menganggap bullying sebagai hal yang normal.\n\nKarena itu bullying bukan urusan korban saja — ini urusan semua orang di lingkungan tersebut.',
	'[{"question":"Siapa saja yang terkena dampak bullying?","options":["Hanya korban","Korban dan pelaku","Korban, pelaku, dan saksi","Tidak ada yang terdampak"],"correct_index":2}]'
),
(
	'Cara Menghadapi Bullying',
	'Keterampilan',
	'article',
	'Langkah praktis saat kamu atau temanmu dirundung.',
	4,
	E'Kalau kamu sedang mengalami bullying, ini yang bisa kamu lakukan:\n\n**1. Jaga keselamatanmu dulu**\nMenjauh dari situasi berbahaya bukan tanda kalah. Keselamatanmu nomor satu.\n\n**2. Tunjukkan sikap tenang**\nPelaku sering mencari reaksi. Jawab singkat dan tegas, lalu pergi.\n\n**3. Catat kejadiannya**\nTulis tanggal, tempat, dan apa yang terjadi. Simpan tangkapan layar jika terjadi online. Ini penting saat melapor.\n\n**4. Cerita ke orang yang kamu percaya**\nOrang tua, guru BK, atau kakak. Kamu tidak harus menghadapi ini sendirian.\n\n**5. Laporkan**\nGunakan fitur Lapor di aplikasi ini. Kamu bisa melapor secara anonim jika belum siap membuka identitas.\n\nKalau kamu melihat teman dirundung: jangan ikut menonton atau tertawa. Ajak korban pergi dari situasi itu, lalu laporkan.',
	'[{"question":"Mengapa mencatat kejadian bullying itu penting?","options":["Agar bisa membalas dendam","Sebagai bukti saat melapor","Supaya bisa dipamerkan","Tidak penting"],"correct_index":1},{"question":"Saat melihat teman dirundung, sikap terbaik adalah...","options":["Ikut tertawa agar tidak jadi korban","Diam dan pura-pura tidak lihat","Ajak korban menjauh lalu laporkan","Merekam untuk hiburan"],"correct_index":2}]'
),
(
	'Cyberbullying & Keamanan Digital',
	'Digital',
	'article',
	'Melindungi diri saat berinteraksi di dunia maya.',
	5,
	E'Cyberbullying terjadi lewat perangkat digital dan punya tantangan khusus: jejaknya cepat menyebar dan bisa terjadi 24 jam.\n\n**Langkah melindungi diri:**\n\n- **Jangan balas.** Membalas sering memperpanjang masalah.\n- **Simpan bukti.** Tangkapan layar sebelum konten dihapus.\n- **Blokir dan laporkan** akun pelaku ke platform terkait.\n- **Kunci privasi akunmu.** Batasi siapa yang bisa melihat unggahanmu.\n- **Jangan bagikan** kata sandi, foto pribadi, atau lokasi rumahmu — bahkan ke teman dekat.\n\n**Jadilah pengguna yang baik:** sebelum mengunggah sesuatu tentang orang lain, tanya dirimu — apakah dia akan merasa nyaman jika ini dilihat banyak orang?',
	'[{"question":"Apa yang sebaiknya dilakukan pertama kali saat menerima pesan kasar online?","options":["Balas dengan kata yang lebih kasar","Simpan bukti lalu blokir dan laporkan","Sebarkan ke grup lain","Hapus semua dan diamkan"],"correct_index":1}]'
);

INSERT INTO training_scenarios (prompt, category, order_index, options) VALUES
(
	'Saat istirahat, kamu melihat temanmu diejek soal bentuk tubuhnya di depan banyak orang. Orang-orang di sekitar tertawa. Apa yang kamu lakukan?',
	'Peran Saksi',
	1,
	'[{"label":"Ikut tertawa supaya tidak dianggap aneh","feedback":"Ikut tertawa membuat korban merasa makin sendirian dan memberi sinyal bahwa perilaku itu diterima. Kamu tidak perlu melawan pelaku secara langsung, tapi kamu juga tidak perlu ikut menertawakan.","is_best":false},{"label":"Diam saja dan pergi menjauh","feedback":"Tidak ikut tertawa sudah lebih baik daripada bergabung. Tapi korban masih sendirian. Langkah kecil seperti mengajaknya pergi bisa sangat berarti.","is_best":false},{"label":"Ajak temanmu pergi dari situ dengan alasan wajar, lalu tanyakan kabarnya","feedback":"Tepat. Mengalihkan situasi tanpa konfrontasi langsung menjaga keselamatan kalian berdua, dan menunjukkan bahwa dia tidak sendirian. Setelah itu kamu bisa mendorongnya melapor.","is_best":true},{"label":"Langsung membentak pelaku di depan umum","feedback":"Niatmu baik, tapi konfrontasi terbuka bisa membuat situasi memanas dan berisiko bagi keselamatanmu. Lebih aman mengalihkan korban lalu melaporkan ke guru.","is_best":false}]'
),
(
	'Seseorang membuat akun palsu memakai fotomu dan mengunggah hal-hal memalukan. Apa langkah pertamamu?',
	'Cyberbullying',
	2,
	'[{"label":"Membuat akun palsu balasan untuk mempermalukan dia","feedback":"Membalas dengan cara yang sama membuatmu ikut melakukan pelanggaran dan memperkeruh masalah. Kamu juga bisa kehilangan posisi sebagai korban di mata pihak sekolah.","is_best":false},{"label":"Tangkap layar semua bukti, lalu laporkan akunnya ke platform dan ke guru","feedback":"Tepat. Bukti adalah hal pertama yang hilang saat pelaku menghapus unggahannya. Setelah bukti aman, pelaporan ke platform dan sekolah bisa berjalan.","is_best":true},{"label":"Diamkan saja, nanti juga hilang sendiri","feedback":"Konten digital jarang hilang sendiri dan bisa menyebar makin luas. Melapor lebih awal membuat penanganannya jauh lebih mudah.","is_best":false},{"label":"Minta semua temanmu menyerang akun itu beramai-ramai","feedback":"Ini berubah menjadi perundungan massal dari sisi lain, dan bisa menghapus bukti sebelum sempat ditangani secara resmi.","is_best":false}]'
),
(
	'Kakak kelas memintamu menyerahkan uang jajan setiap hari sambil mengancam. Kamu takut dia membalas kalau kamu bilang ke siapa pun.',
	'Korban',
	3,
	'[{"label":"Terus memberi uang supaya aman","feedback":"Menuruti permintaan biasanya membuat tuntutan bertambah, bukan berhenti. Rasa takutmu wajar, tapi ini tidak akan selesai dengan sendirinya.","is_best":false},{"label":"Catat kejadiannya dan laporkan secara anonim lewat fitur Lapor","feedback":"Tepat. Pelaporan anonim ada justru untuk situasi seperti ini — kamu bisa menyampaikan kejadiannya tanpa identitasmu tercatat, dan tetap memantau tindak lanjutnya lewat kode tiket.","is_best":true},{"label":"Mengancam balik dengan bantuan teman-temanmu","feedback":"Ini berisiko meningkat menjadi kekerasan fisik dan bisa membuatmu ikut dianggap bersalah. Jalur pelaporan lebih aman dan lebih efektif.","is_best":false},{"label":"Pindah sekolah tanpa memberi tahu siapa pun","feedback":"Menghindar mungkin terasa melegakan, tapi pelaku akan melanjutkan hal yang sama ke orang lain. Melapor dulu adalah langkah yang melindungi kamu dan yang lain.","is_best":false}]'
),
(
	'Temanmu mengirim pesan: "Aku capek, kayaknya nggak ada yang bakal peduli kalau aku hilang." Dia sudah lama jadi korban bullying.',
	'Mendukung Teman',
	4,
	'[{"label":"Balas \"jangan lebay ah\" supaya suasananya cair","feedback":"Bercanda saat seseorang menyampaikan perasaan seberat ini membuat dia menyesal sudah terbuka dan kemungkinan besar tidak akan bercerita lagi.","is_best":false},{"label":"Dengarkan tanpa menghakimi, tetap temani, dan segera beri tahu orang dewasa yang dipercaya","feedback":"Tepat. Pesan seperti ini harus selalu dianggap serius. Kamu tidak perlu menyelesaikannya sendirian — tugasmu adalah menemani dan menghubungkan dia dengan orang dewasa yang bisa menolong.","is_best":true},{"label":"Simpan sendiri karena dia memintamu merahasiakan","feedback":"Menjaga rahasia teman penting, tapi keselamatan lebih penting daripada janji rahasia. Ini satu-satunya situasi di mana melibatkan orang dewasa adalah tindakan yang benar meski dia keberatan.","is_best":false},{"label":"Sebarkan pesannya ke grup kelas agar banyak yang menghibur","feedback":"Menyebarkan pesan pribadinya melanggar kepercayaannya dan bisa memperburuk keadaannya. Sampaikan langsung ke guru BK atau orang tua, bukan ke grup.","is_best":false}]'
);
